$ScriptRoot = if ($PSScriptRoot) {
    $PSScriptRoot
}
elseif ($MyInvocation.MyCommand.Path) {
    Split-Path -Parent $MyInvocation.MyCommand.Path
}
else {
    Get-Location | Select-Object -ExpandProperty Path
}

##================================================
## MARK: Logging Setup (hardened — never crashes)
##================================================
$preferredLogDir = "C:\ProgramData\G1001\Packages\$packageName"
$fallbackLogDir  = Join-Path $env:WINDIR "Temp\G1001-Packages\$packageName"

$logDir = $null
foreach ($candidate in @($preferredLogDir, $fallbackLogDir)) {
    try {
        if (-not (Test-Path -Path $candidate)) {
            New-Item -Path $candidate -ItemType Directory -Force -ErrorAction Stop | Out-Null
        }
        # Confirm we can actually write to it
        $probe = Join-Path $candidate ".write_probe_$([guid]::NewGuid().ToString('N')).tmp"
