    try {
        $bootstrapLine = "[$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')] [Info] Log file initialized at $logFile`r`n"
        [System.IO.File]::AppendAllText($logFile, $bootstrapLine, [System.Text.Encoding]::UTF8)
