##================================================
## MARK: Stop Running Processes
##================================================
if ($processToStop -and $processToStop.Count -gt 0) {
    Write-Log "Stopping process(es) matching: $($processToStop -join ', ')" -Level Info
    foreach ($procName in $processToStop) {
        if ([string]::IsNullOrWhiteSpace($procName)) { continue }
        $running = Get-Process -Name $procName -ErrorAction SilentlyContinue
        if ($running) {
            $count = ($running | Measure-Object).Count
            Write-Log "Stopping $count instance(s) of '$procName'..." -Level Info
            $running | Stop-Process -Force -ErrorAction SilentlyContinue
            Start-Sleep -Milliseconds 500
            $stillRunning = Get-Process -Name $procName -ErrorAction SilentlyContinue
            if ($stillRunning) {
                Write-Log "WARNING: '$procName' is still running after stop attempt." -Level Warning
            }
            else {
                Write-Log "'$procName' stopped successfully." -Level Success
            }
        }
        else {
            Write-Log "No running instance of '$procName' found, skipping." -Level Info
        }
    }
}
else {
    Write-Log "No processes specified to stop." -Level Info
}

##================================================
## MARK: Resolve Installer Path  ($PSScriptRoot fix)
##================================================
# This is the critical Intune fix. Resolve installer relative to the script's
# folder, NOT the working directory. The Intune SYSTEM-context working dir is
# often C:\Windows\System32 — passing just the filename to msiexec from there
# fails with error 1619 ("package could not be opened").
if ([System.IO.Path]::IsPathRooted($installerName)) {
    $installerPath = $installerName
}
else {
    $installerPath = Join-Path $ScriptRoot $installerName
}
Write-Log "Resolved installer path: $installerPath" -Level Info

if (-not (Test-Path -Path $installerPath -PathType Leaf)) {
    Write-Log "Installer file not found at: $installerPath" -Level Error
    Write-Log "Contents of script root for diagnosis:" -Level Error
    Get-ChildItem -Path $ScriptRoot -ErrorAction SilentlyContinue | ForEach-Object {
        Write-Log "  $($_.Name)  ($($_.Length) bytes)" -Level Error
    }
    exit 1
}

##================================================
## MARK: Build Command Line
##================================================
if ($installerType -eq 'MSI') {
    $msiAction  = if ($DeploymentType -eq 'Install') { '/i' } else { '/x' }
    $msiLogPath = if ($logDir) {
        Join-Path $logDir "${packageName}_${DeploymentType}_msiexec_${timeStamp}.log"
    } else {
        Join-Path $env:WINDIR "Temp\${packageName}_${DeploymentType}_msiexec.log"
    }

    # Use the FULL resolved path here, NOT $installerName
    $msiArgs = @(
        $msiAction
        "`"$installerPath`""
    )
    if (-not [string]::IsNullOrWhiteSpace($arguments)) {
        $msiArgs += $arguments
    }
    $msiArgs += '/L*v'
    $msiArgs += "`"$msiLogPath`""

    $exeToRun = "$env:SystemRoot\System32\msiexec.exe"
    $argLine  = $msiArgs -join ' '

    Write-Log "MSI verbose log: $msiLogPath" -Level Info
}
else {
    $exeToRun = $installerPath
    $argLine  = $arguments
}

Write-Log "Executing: $exeToRun $argLine" -Level Info

##================================================
## MARK: Execute
##================================================
try {
    $startParams = @{
        FilePath    = $exeToRun
        Wait        = $true
        PassThru    = $true
        NoNewWindow = $true
    }
    if (-not [string]::IsNullOrWhiteSpace($argLine)) {
        $startParams['ArgumentList'] = $argLine
    }
    $proc = Start-Process @startParams
    $exitCode = $proc.ExitCode
    Write-Log "Process exited with code: $exitCode" -Level Info
}
catch {
    Write-Log "Failed to launch installer: $_" -Level Error
    exit 1
}

##================================================
