    ##================================================
    Write-Log "Managing Snagit shortcuts..." -Level Info

    # Define shortcut locations
    $publicDesktop = [Environment]::GetFolderPath('CommonDesktopDirectory')
    $publicStartMenu = [Environment]::GetFolderPath('CommonStartMenu')
    $startMenuPrograms = Join-Path $publicStartMenu 'Programs'

    # Define shortcut names and target paths
    $shortcuts = @(
        @{
            Name = 'Snagit 12'
            Target = 'C:\Program Files (x86)\techsmith\snagit\Snagit.exe'
