        }
    )

    foreach ($shortcut in $shortcuts) {
        $shortcutName = $shortcut.Name
        $targetPath = $shortcut.Target

        # Check if target exists
        if (-not (Test-Path -Path $targetPath)) {
            Write-Log "WARNING: Target not found for $shortcutName : $targetPath" -Level Warning
            continue
        }

        # Remove existing shortcuts from Desktop
        $desktopShortcut = Join-Path $publicDesktop "$shortcutName.lnk"
        if (Test-Path -Path $desktopShortcut) {
            try {
                Remove-Item -Path $desktopShortcut -Force -ErrorAction Stop
                Write-Log "Removed existing Desktop shortcut: $shortcutName" -Level Info
            }
            catch {
                Write-Log "Failed to remove Desktop shortcut for $shortcutName : $_" -Level Warning
            }
        }

        # Remove existing shortcuts from Start Menu
        $startMenuShortcut = Join-Path $startMenuPrograms "$shortcutName.lnk"
        if (Test-Path -Path $startMenuShortcut) {
            try {
                Remove-Item -Path $startMenuShortcut -Force -ErrorAction Stop
                Write-Log "Removed existing Start Menu shortcut: $shortcutName" -Level Info
            }
            catch {
                Write-Log "Failed to remove Start Menu shortcut for $shortcutName : $_" -Level Warning
            }
        }

        # Create new Desktop shortcut
        try {
            $wshShell = New-Object -ComObject WScript.Shell
            $desktopShortcutObj = $wshShell.CreateShortcut($desktopShortcut)
            $desktopShortcutObj.TargetPath = $targetPath
            $desktopShortcutObj.WorkingDirectory = Split-Path -Parent $targetPath
            $desktopShortcutObj.Save()
            Write-Log "Created Desktop shortcut: $shortcutName" -Level Success
        }
        catch {
            Write-Log "Failed to create Desktop shortcut for $shortcutName : $_" -Level Error
